//! Identifier aliases. All ids are UUIDv7 (time-ordered) generated by Postgres
//! (`uuid_generate_v7()`); the aliases document intent at call sites.

use uuid::Uuid;

pub type TenantId = Uuid;
pub type UserId = Uuid;
pub type GroupId = Uuid;
pub type TopicId = Uuid;
pub type AssignmentId = Uuid;
pub type SourceId = Uuid;
pub type MomentId = Uuid;
pub type GenerationJobId = Uuid;
pub type ReelId = Uuid;
pub type QuestionId = Uuid;
pub type PlanId = Uuid;
pub type PlanItemId = Uuid;
pub type JobId = Uuid;
pub type MediaAssetId = Uuid;
pub type ExportId = Uuid;
pub type ChallengeId = Uuid;

/// A new time-ordered id for rows created in application code (tests, seeds).
pub fn new_id() -> Uuid {
    Uuid::now_v7()
}
